/*
 * storybook-score / score.mjs — a complete, editable picture-book score.
 *
 * One 3/4 arrangement at 72 BPM, base key F major, 16 bars = 40.0 s, on the current
 * Viscraft sound contract. The music is arranged here, not sampled: every voice
 * is generated by synth.mjs from oscillators, seeded noise and filters. There is
 * no fetch, no audio asset and no hidden recording.
 *
 * Form:
 *   opening  0.0-5.0    music-box motif alone (theme, octave up)
 *   toys     5.0-12.5   toy piano + reed change; rising answer; reed wind-down
 *   rest    12.5-15.0   one silent bar, no new attacks (gated)
 *   theme   15.0-25.0   the complete 4-bar theme: flute lead, music-box
 *                       doubling, reed counter-line, harp bass
 *   cadence 25.0-27.5   cadence in the sounding key
 *   coda    27.5-40.0   music-box answer, playback rate 1 -> 0.93 (onsets and
 *                       pitch slow together), then the room rings out
 *
 * `buildScore` returns the descriptor. `renderScore` takes only params (plus the
 * clock and seed) and rebuilds the descriptor internally; it never accepts a
 * caller-supplied descriptor. It returns exactly the requested sample span. The
 * only musical inputs are variant, transpose and gain; there is no `seconds`
 * option that could silently cut a phrase.
 *
 * Adapted material (LemoLab, MIT, lemo-opuscar@e3cb16f6): the 4-bar THEME
 * phrase, the toy-piano/reed change, the breath/wind-down gesture, the silent
 * rest and the winding-down coda follow styles/crayon-book/demo/music/score.py;
 * the music-box/harp/toy synthesis follows core/audio/pluck.py and score.py as
 * recorded in synth.mjs and LICENSES.md. The arrangement, flute and
 * reed voices, alternate orchestration and every timing here are original.
 */
import { mulberry32, room, synthesize } from './synth.mjs';

export const BPM = 72;
export const BEATS_PER_BAR = 3;
export const BAR_SECONDS = (60 / BPM) * BEATS_PER_BAR; // 2.5 s
export const BARS = 16;
export const SECONDS = BARS * BAR_SECONDS; // 40.0 s
export const FPS = 24;
export const FRAMES = SECONDS * FPS; // 960
export const DEFAULT_SEED = 7207;

export const DEFAULT_PARAMS = Object.freeze({ variant: 'base', transpose: 0, gain: 1 });

const PARAM_KEYS = new Set(['variant', 'transpose', 'gain']);
const VARIANTS = new Set(['base', 'alternate']);
const BEAT = 60 / BPM; // 0.8333 s
const BAR = BAR_SECONDS;

// The recognizable 4-bar theme (F | Bb | C7 | F), in beats within each bar.
const THEME = [
  [
    ['F4', 0, 0.5, 0.82],
    ['A4', 0.5, 0.5, 0.78],
    ['C5', 1, 1.5, 0.86],
    ['A4', 2.5, 0.5, 0.72],
  ],
  [
    ['D5', 0, 1, 0.84],
    ['C5', 1, 0.5, 0.76],
    ['Bb4', 1.5, 0.5, 0.74],
    ['A4', 2, 1, 0.8],
  ],
  [
    ['G4', 0, 0.5, 0.78],
    ['Bb4', 0.5, 0.5, 0.76],
    ['E5', 1, 1.5, 0.88],
    ['D5', 2.5, 0.5, 0.76],
  ],
  [['C5', 0, 3, 0.82]],
];

const NOTE_OFFSETS = { C: 0, D: 2, E: 4, F: 5, G: 7, A: 9, B: 11 };

export function parsePitch(name) {
  const match = /^\s*([A-Ga-g])([#b]?)(-?\d+)\s*$/.exec(String(name));
  if (!match) throw new Error(`storybook-score: cannot parse pitch ${JSON.stringify(name)}`);
  const accidental = match[2] === '#' ? 1 : match[2] === 'b' ? -1 : 0;
  return 12 * (Number(match[3]) + 1) + NOTE_OFFSETS[match[1].toUpperCase()] + accidental;
}

/** Only variant / transpose / gain. Unknown keys are a loud authoring error. */
export function normalizeParams(raw = {}) {
  if (raw === null || typeof raw !== 'object' || Array.isArray(raw))
    throw new Error('storybook-score params must be a plain object');
  for (const key of Object.keys(raw))
    if (!PARAM_KEYS.has(key))
      throw new Error(
        `storybook-score does not take the param "${key}"; only ${[...PARAM_KEYS].join(', ')} ` +
          '(the model is a fixed 40 s form, so there is no seconds/truncation knob)',
      );
  const variant = raw.variant ?? DEFAULT_PARAMS.variant;
  const transpose = raw.transpose ?? DEFAULT_PARAMS.transpose;
  const gain = raw.gain ?? DEFAULT_PARAMS.gain;
  if (!VARIANTS.has(variant)) throw new Error('storybook-score variant must be "base" or "alternate"');
  if (!Number.isInteger(transpose) || transpose < -12 || transpose > 12)
    throw new Error('storybook-score transpose must be an integer number of semitones in [-12, 12]');
  if (!Number.isFinite(gain) || gain < 0 || gain > 1) throw new Error('storybook-score gain must be between 0 and 1');
  return { variant, transpose, gain };
}

export const STEM_GAINS = Object.freeze({
  musicbox: 0.66,
  toy: 0.62,
  flute: 0.58,
  reed: 0.78,
  harp: 0.82,
});

const SECTIONS = [
  {
    id: 'opening',
    start: 0,
    end: 5,
    beats: { start: 0, end: 6 },
    label: 'music-box motif alone, two bars',
    dynamics: { musicbox: 1, toy: 0.4, flute: 0.5, reed: 0.45, harp: 0.4 },
  },
  {
    id: 'toys',
    start: 5,
    end: 12.5,
    beats: { start: 6, end: 15 },
    label: 'toy piano and reed change, rising answer, reed wind-down',
    dynamics: { musicbox: 0.58, toy: 1, flute: 0.5, reed: 0.92, harp: 0.55 },
  },
  {
    id: 'rest',
    start: 12.5,
    end: 15,
    beats: { start: 15, end: 18 },
    label: 'one silent bar: no new attacks, all buses gated',
    dynamics: { musicbox: 0, toy: 0, flute: 0, reed: 0, harp: 0 },
  },
  {
    id: 'theme',
    start: 15,
    end: 25,
    beats: { start: 18, end: 30 },
    label: 'complete four-bar theme: flute, music box, counter-line, harp bass',
    dynamics: { musicbox: 0.58, toy: 0.4, flute: 1, reed: 0.86, harp: 0.9 },
  },
  {
    id: 'cadence',
    start: 25,
    end: 27.5,
    beats: { start: 30, end: 33 },
    label: 'cadence in the sounding key with a long bass',
    dynamics: { musicbox: 1, toy: 0.62, flute: 0.8, reed: 0.9, harp: 0.9 },
  },
  {
    id: 'coda',
    start: 27.5,
    end: 40,
    beats: { start: 33, end: 48 },
    label: 'music-box answer, playback rate 1 -> 0.93, room rings out',
    dynamics: { musicbox: 1, toy: 0.5, flute: 0.45, reed: 0.5, harp: 0.7 },
  },
];

const VARIANT_ROLES = Object.freeze({
  opening: 'motif',
  toys: 'reorchestration',
  rest: 'rest',
  theme: 'theme',
  cadence: 'cadence',
  coda: 'winddown',
});

function sectionById(id) {
  const section = SECTIONS.find(candidate => candidate.id === id);
  if (!section) throw new Error(`storybook-score: unknown section ${id}`);
  return section;
}

// ---------------------------------------------------------------------------
// The continuous coda clock. The renderer advances its source read position by
// `rate(outputTime)` per output sample; this table integrates the same curve so
// descriptor onsets and rendered onsets agree.
// ---------------------------------------------------------------------------

export const CODA_RATE_START = 1;
export const CODA_RATE_END = 0.93;
export const CODA_RAMP_SECONDS = 6;
export const CODA_CURVE_POWER = 1.5;
export const CODA_SOURCE_SECONDS = 12.0;

function codaRateAt(outputTime) {
  const ramp = Math.min(1, Math.max(0, outputTime / CODA_RAMP_SECONDS));
  return CODA_RATE_START + (CODA_RATE_END - CODA_RATE_START) * ramp ** CODA_CURVE_POWER;
}

function makeCodaClock(sourceSeconds, sampleRate) {
  const stepSeconds = sampleRate ? 1 / sampleRate : 0.0005;
  const steps = Math.ceil(sourceSeconds / stepSeconds) + 2;
  const times = new Float64Array(steps);
  let output = 0;
  for (let i = 0; i < steps; i++) {
    times[i] = output;
    output += stepSeconds / codaRateAt(output);
  }
  const at = sourceTime => {
    const clamped = Math.max(0, Math.min(sourceSeconds, sourceTime));
    const exact = clamped / stepSeconds;
    const index = Math.min(steps - 2, Math.floor(exact));
    const fraction = exact - index;
    return times[index] * (1 - fraction) + times[index + 1] * fraction;
  };
  return { at, total: at(sourceSeconds) };
}

// ---------------------------------------------------------------------------
// buildScore
// ---------------------------------------------------------------------------

/**
 * Build the complete arrangement descriptor. Pure: same params → same object.
 * Times are seconds on the authored timeline; `midi` already includes transpose.
 */
export function buildScore(rawParams = {}) {
  const params = normalizeParams(rawParams);
  const { variant, transpose, gain } = params;
  const events = [];
  const add = (section, voice, pitch, time, duration, eventGain, pan, velocity = eventGain) => {
    const midi = parsePitch(pitch) + transpose;
    events.push({
      id: '',
      section,
      role: VARIANT_ROLES[section],
      voice,
      midi,
      time: roundTime(time),
      duration: roundTime(duration),
      gain: eventGain,
      velocity,
      pan,
      coda: false,
    });
  };

  const themeEvent = (bar, beat, duration) => {
    const t0 = 15 + bar * BAR;
    return { at: t0 + beat * BEAT, hold: duration * BEAT };
  };

  // ---- opening: music-box motif alone -----------------------------------
  for (let bar = 0; bar < 2; bar++) {
    const t0 = bar * BAR;
    for (const [pitch, beat, duration, level] of THEME[bar]) {
      add('opening', 'musicbox', transposePitch(pitch, 12), t0 + beat * BEAT, duration * BEAT, level, 0.12);
    }
    const root = bar === 0 ? 'F3' : 'Bb3';
    add('opening', 'musicbox', root, t0, BAR * 0.9, 0.34, -0.18, 0.34);
  }
  if (variant === 'alternate') {
    // A quiet reed drone changes the opening colour without replacing the motif.
    add('opening', 'reed', 'F2', 0.0, 4.9, 0.28, -0.32, 0.28);
  }
  add('opening', 'musicbox', 'C7', 4.72, 0.25, 0.3, 0.3, 0.3);

  // ---- toys: toy piano + reed change -----------------------------------
  const toyChords = [
    ['F3', ['A4', 'C5']],
    ['C3', ['G4', 'Bb4']],
    ['F3', ['A4', 'C5']],
  ];
  for (let bar = 0; bar < 3; bar++) {
    const t0 = 5 + bar * BAR;
    const [root, chord] = toyChords[bar];
    const rootMidi = parsePitch(root);
    const reedPitch = rootMidi < 50 ? transposePitch(root, 12) : root;
    add('toys', 'reed', reedPitch, t0, 0.28, bar === 0 ? 0.86 : 0.72, -0.26, 0.72);
    if (variant === 'base') {
      for (let beat = 1; beat <= 2; beat++) {
        for (const pitch of chord) {
          add('toys', 'toy', pitch, t0 + beat * BEAT, 0.4, beat === 1 ? 0.62 : 0.56, -0.12 + beat * 0.11);
        }
      }
    } else {
      // Alternate: the music box takes the oom-pah and the toy keeps the reed's
      // rhythmic answer, so the change is real orchestration, not a gain tweak.
      for (let beat = 0; beat <= 2; beat++) {
        for (const pitch of chord) {
          add('toys', 'musicbox', transposePitch(pitch, 12), t0 + beat * BEAT, 0.22, 0.38, -0.2 + beat * 0.14);
        }
      }
      add('toys', 'toy', chord[0], t0 + 2 * BEAT, 0.4, 0.6, 0.24);
    }
  }
  // Turning accents at the section start and the middle bar.
  for (const time of [5.0, 7.5]) {
    for (const pitch of ['F4', 'C5', 'F5']) add('toys', 'toy', pitch, time, 0.5, 0.82, 0.2, 0.82);
    const reedAccent = time === 5.0 ? 'F3' : 'C3';
    add('toys', 'reed', reedAccent, time, 0.3, 0.78, -0.2, 0.78);
  }
  // Rising answer. The alternate uses a different phrase and start time.
  if (variant === 'base') {
    const answer = ['C5', 'D5', 'E5', 'F5'];
    for (let i = 0; i < answer.length; i++) {
      const time = 10 + i * 0.55;
      add('toys', 'toy', answer[i], time, 0.42, 0.8, -0.3 + i * 0.15, 0.8);
      add('toys', 'musicbox', transposePitch(answer[i], 12), time, 0.3, 0.34, -0.3 + i * 0.15, 0.34);
    }
    // Reed wind-down, still clear of the rest gate.
    add('toys', 'reed', 'Bb3', 11.95, 0.18, 0.56, 0.08, 0.56);
    add('toys', 'reed', 'A3', 12.2, 0.18, 0.52, 0.08, 0.52);
  } else {
    const answer = ['C5', 'E5', 'G5', 'Bb5'];
    for (let i = 0; i < answer.length; i++) {
      const time = 9.85 + i * 0.55;
      add('toys', 'toy', answer[i], time, 0.42, 0.82, -0.26 + i * 0.14, 0.82);
      add('toys', 'musicbox', transposePitch(answer[i], 12), time, 0.3, 0.36, 0.2 - i * 0.08, 0.36);
    }
    add('toys', 'reed', 'F3', 11.9, 0.3, 0.6, -0.12, 0.6);
    add('toys', 'toy', 'C6', 11.9, 0.4, 0.62, 0.26, 0.62);
  }

  // ---- theme: complete four bars ---------------------------------------
  if (variant === 'base') {
    for (let bar = 0; bar < 4; bar++) {
      for (const [pitch, beat, duration, level] of THEME[bar]) {
        const { at, hold } = themeEvent(bar, beat, duration);
        add('theme', 'flute', pitch, at, hold + 0.08, level, 0.1, level);
        add('theme', 'musicbox', transposePitch(pitch, 12), at, hold * 0.9, 0.44, -0.18, 0.44);
      }
    }
    // Reed counter-line below the flute.
    const counter = [
      ['A3', 0, 1.5],
      ['C4', 1.5, 1.5],
      ['Bb3', 3, 1.5],
      ['D4', 4.5, 1.5],
      ['Bb3', 6, 1.5],
      ['G3', 7.5, 1.5],
      ['A3', 9, 3],
    ];
    for (const [pitch, beat, duration] of counter) {
      add('theme', 'reed', pitch, 15 + beat * BEAT, duration * BEAT, 0.42, -0.3, 0.42);
    }
    // Harp bass: root, fifth, octave in every bar.
    const roots = ['F2', 'Bb2', 'C3', 'F2'];
    for (let bar = 0; bar < 4; bar++) {
      const t0 = 15 + bar * BAR;
      add('theme', 'harp', roots[bar], t0, 2.2, 0.8, -0.05, 0.8);
      add('theme', 'harp', transposePitch(roots[bar], 7), t0 + BEAT, 1.4, 0.52, 0.05, 0.52);
      add('theme', 'harp', transposePitch(roots[bar], 12), t0 + 2 * BEAT, 1.4, 0.46, 0.1, 0.46);
    }
  } else {
    const harmony = [
      ['F4', 'A4', 'C5'],
      ['Bb4', 'D5', 'F5'],
      ['C5', 'E5', 'G5'],
      ['F4', 'A4', 'C5'],
    ];
    for (let bar = 0; bar < 4; bar++) {
      for (const [pitch, beat, duration, level] of THEME[bar]) {
        const { at, hold } = themeEvent(bar, beat, duration);
        add('theme', 'flute', pitch, at, hold + 0.12, level * 1.02, 0.12, level);
      }
      // Music box plays a broken chord instead of doubling the melody.
      const chord = harmony[bar];
      for (let step = 0; step < 6; step++) {
        add(
          'theme',
          'musicbox',
          transposePitch(chord[step % chord.length], 12),
          15 + bar * BAR + step * 0.42,
          0.36,
          0.32 + (step === 0 ? 0.06 : 0),
          -0.22 + (step % 3) * 0.16,
          0.32,
        );
      }
    }
    // A different descending counter-line.
    const counter = [
      ['C4', 0, 1.5],
      ['A3', 1.5, 1.5],
      ['D4', 3, 1.5],
      ['Bb3', 4.5, 1.5],
      ['G3', 6, 1.5],
      ['E3', 7.5, 1.5],
      ['F3', 9, 3],
    ];
    for (const [pitch, beat, duration] of counter) {
      add('theme', 'reed', pitch, 15 + beat * BEAT, duration * BEAT, 0.4, -0.32, 0.4);
    }
    // Harp walking bass: root, third, fifth.
    const walking = [
      ['F2', 'A2', 'C3'],
      ['Bb2', 'D3', 'F3'],
      ['C3', 'E3', 'G3'],
      ['F2', 'A2', 'C3'],
    ];
    for (let bar = 0; bar < 4; bar++) {
      for (let beat = 0; beat < 3; beat++) {
        add('theme', 'harp', walking[bar][beat], 15 + bar * BAR + beat * BEAT, 1.35, beat === 0 ? 0.76 : 0.5, -0.04 + beat * 0.05, beat === 0 ? 0.76 : 0.5);
      }
    }
  }
  // Sparkle into the cadence.
  for (let i = 0; i < 3; i++) {
    add('theme', 'musicbox', transposePitch(['F5', 'A5', 'C6'][i], 12), 24.45 + i * 0.07, 0.3, 0.3, -0.28 + i * 0.22, 0.3);
  }

  // ---- cadence ----------------------------------------------------------
  if (variant === 'base') {
    for (let i = 0; i < 4; i++) {
      add('cadence', 'musicbox', ['F4', 'A4', 'C5', 'F5'][i], 25.0 + i * 0.09, 0.8, 0.82, -0.2 + i * 0.15, 0.82);
    }
    add('cadence', 'reed', 'F3', 25.0, 2.3, 0.7, -0.2, 0.7);
    add('cadence', 'harp', 'F2', 25.0, 3.0, 0.8, 0, 0.8);
    add('cadence', 'flute', 'A5', 26.2, 0.5, 0.46, 0.24, 0.46);
    add('cadence', 'musicbox', 'C6', 26.55, 0.35, 0.32, 0.2, 0.32);
  } else {
    for (let i = 0; i < 4; i++) {
      add('cadence', 'toy', ['F4', 'A4', 'C5', 'F5'][i], 25.0 + i * 0.08, 0.7, 0.82, -0.18 + i * 0.14, 0.82);
    }
    add('cadence', 'reed', 'F3', 25.0, 2.3, 0.74, -0.22, 0.74);
    add('cadence', 'harp', 'F2', 25.0, 3.0, 0.82, 0, 0.82);
    add('cadence', 'flute', 'A4', 25.3, 1.2, 0.5, 0.22, 0.5);
    add('cadence', 'musicbox', 'C6', 26.4, 0.35, 0.34, 0.2, 0.34);
  }

  // ---- coda: music-box answer, rate 1 -> 0.93 ---------------------------
  const codaNotes =
    variant === 'base'
      ? [
          [0.0, 'F5', 1.6, 0.78],
          [0.85, 'A5', 1.4, 0.66],
          [1.7, 'C6', 1.3, 0.62],
          [2.6, 'A5', 1.8, 0.58],
          [3.6, 'F5', 1.6, 0.6],
          [4.45, 'A5', 1.4, 0.54],
          [5.35, 'C6', 1.3, 0.5],
          [6.3, 'A5', 1.8, 0.46],
          [7.3, 'F5', 1.6, 0.48],
          [8.35, 'F5', 1.8, 0.5],
          [8.35, 'C5', 1.8, 0.32],
          [9.15, 'F4', 2.4, 0.5],
        ]
      : [
          [0.0, 'F5', 1.6, 0.78],
          [0.9, 'G5', 1.4, 0.68],
          [1.85, 'A5', 1.3, 0.64],
          [2.9, 'C6', 1.8, 0.6],
          [4.2, 'A5', 1.5, 0.56],
          [5.2, 'G5', 1.4, 0.5],
          [6.2, 'F5', 1.6, 0.48],
          [7.2, 'C5', 1.8, 0.44],
          [8.25, 'F4', 2.4, 0.5],
        ];
  const codaNotesWithIds = codaNotes.map(([sourceTime, pitch, duration, level], index) => ({
    id: `coda-${index + 1}`,
    section: 'coda',
    role: 'winddown',
    voice: 'musicbox',
    midi: parsePitch(pitch) + transpose,
    sourceTime,
    duration,
    gain: level,
    velocity: level,
    pan: 0.08 + Math.sin(index * 0.7) * 0.18,
    coda: true,
  }));
  if (variant === 'alternate') {
    // The alternate coda is toy-doubled and ends on a reed root: different
    // orchestration and a different answer phrase, not a different seed.
    const doubles = [0, 1, 2, 3];
    for (const index of doubles) {
      const note = codaNotesWithIds[index];
      codaNotesWithIds.push({
        id: `coda-toy-${index + 1}`,
        section: 'coda',
        role: 'winddown',
        voice: 'toy',
        midi: note.midi - 12,
        sourceTime: note.sourceTime,
        duration: 1.2,
        gain: 0.5,
        velocity: 0.5,
        pan: -0.24,
        coda: true,
      });
    }
    codaNotesWithIds.push({
      id: 'coda-reed',
      section: 'coda',
      role: 'winddown',
      voice: 'reed',
      midi: parsePitch('F3') + transpose,
      sourceTime: 8.9,
      duration: 1.8,
      gain: 0.42,
      velocity: 0.42,
      pan: -0.1,
      coda: true,
    });
  }

  const clock = makeCodaClock(CODA_SOURCE_SECONDS);
  const codaMap = codaNotesWithIds.map(note => {
    const start = clock.at(note.sourceTime);
    const end = clock.at(note.sourceTime + note.duration);
    return {
      id: note.id,
      sourceTime: note.sourceTime,
      time: roundTime(27.5 + start),
      duration: roundTime(end - start),
      rate: roundTime(note.duration / Math.max(end - start, 1e-6)),
    };
  });
  for (let i = 0; i < codaNotesWithIds.length; i++) {
    const note = codaNotesWithIds[i];
    const mapped = codaMap[i];
    events.push({
      id: note.id,
      section: 'coda',
      role: 'winddown',
      voice: note.voice,
      midi: note.midi,
      time: mapped.time,
      duration: mapped.duration,
      gain: note.gain,
      velocity: note.velocity,
      pan: note.pan,
      coda: true,
      sourceTime: note.sourceTime,
      rate: mapped.rate,
      transform: 'resample',
    });
  }

  // Stable ids and a time-sorted list; the renderer consumes `coda.notes` for
  // the transformed part and the rest by `time`.
  let normalIndex = 0;
  for (const event of events) {
    if (!event.coda) event.id = `ev-${++normalIndex}`;
  }
  events.sort((a, b) => a.time - b.time || a.id.localeCompare(b.id));

  const stems = Object.fromEntries(Object.entries(STEM_GAINS).map(([voice, level]) => [voice, { gain: level }]));
  const rest = { start: 12.5, end: 15, scope: 'all', gate: true, fadeSeconds: 0.03 };

  const lastCodaSource = Math.max(...codaNotesWithIds.map(note => note.sourceTime));
  const codaLastTime = roundTime(27.5 + clock.at(lastCodaSource));

  const cues =
    variant === 'base'
      ? [
          { id: 'open', time: 0, label: 'music-box motif enters' },
          { id: 'toys', time: 5, label: 'toy piano and reed change' },
          { id: 'answer', time: 10, label: 'rising answer begins' },
          { id: 'rest', time: 12.5, label: 'one silent bar' },
          { id: 'theme', time: 15, label: 'complete four-bar theme' },
          { id: 'cadence', time: 25, label: 'cadence in the sounding key' },
          { id: 'coda', time: 27.5, label: 'winding-down coda' },
          { id: 'last', time: codaLastTime, label: 'last music-box root' },
        ]
      : [
          { id: 'open', time: 0, label: 'music-box motif with reed drone' },
          { id: 'toys', time: 5, label: 'swapped toy/music-box change' },
          { id: 'answer', time: 9.85, label: 'alternate rising answer' },
          { id: 'turn', time: 11.9, label: 'music-box turn into the rest' },
          { id: 'rest', time: 12.5, label: 'one silent bar' },
          { id: 'theme', time: 15, label: 'complete four-bar theme, re-orchestrated' },
          { id: 'cadence', time: 25, label: 'toy-piano cadence' },
          { id: 'coda', time: 27.5, label: 'winding-down coda, toy-doubled' },
          { id: 'last', time: codaLastTime, label: 'last doubled answer note' },
        ];

  // The last audible moment plus a conservative ring; the renderer refuses a
  // span shorter than this instead of cutting the final phrase.
  const normalEnd = events
    .filter(event => !event.coda)
    .reduce((end, event) => Math.max(end, event.time + event.duration + 0.3), 0);
  const codaEnd = codaMap.reduce((end, note) => Math.max(end, note.time + note.duration), 0) + 1.8;
  // The authored programme is exactly 40 s; the tail fade ends the last ring.
  const audibleEnd = Math.min(SECONDS, Math.max(normalEnd, codaEnd, SECONDS - 1.25));

  return {
    version: 1,
    params: { ...params },
    variant,
    transpose,
    gain,
    meter: '3/4',
    meterSpec: { beats: 3, unit: 4 },
    meterLabel: '3/4',
    baseKey: 'F major',
    key: midiToKeyName(parsePitch('F4') + transpose),
    bpm: BPM,
    beatsPerBar: BEATS_PER_BAR,
    barSeconds: BAR_SECONDS,
    bars: BARS,
    seconds: SECONDS,
    fps: FPS,
    frames: FRAMES,
    audibleEnd: roundTime(audibleEnd),
    stems,
    sections: SECTIONS.map(section => ({
      ...section,
      role: VARIANT_ROLES[section.id],
      dynamics: { ...section.dynamics },
    })),
    events,
    rests: [rest],
    cues: cues.map(cue => ({ ...cue, time: roundTime(cue.time) })),
    coda: {
      start: 27.5,
      end: 40,
      sourceSeconds: CODA_SOURCE_SECONDS,
      rateStart: CODA_RATE_START,
      rateEnd: CODA_RATE_END,
      rampSeconds: CODA_RAMP_SECONDS,
      curvePower: CODA_CURVE_POWER,
      notes: codaNotesWithIds,
      map: [...codaMap].sort((a, b) => a.time - b.time || a.id.localeCompare(b.id)),
      lastOnset: codaLastTime,
    },
  };
}

function transposePitch(name, semitones) {
  return midiToName(parsePitch(name) + semitones);
}

const NOTE_NAMES = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
function midiToName(midi) {
  const rounded = Math.round(midi);
  return `${NOTE_NAMES[((rounded % 12) + 12) % 12]}${Math.floor(rounded / 12) - 1}`;
}

function midiToKeyName(midi) {
  const rounded = Math.round(midi);
  return `${NOTE_NAMES[((rounded % 12) + 12) % 12]} major`;
}

function roundTime(value) {
  return Math.round(value * 1e6) / 1e6;
}

// ---------------------------------------------------------------------------
// Rendering
// ---------------------------------------------------------------------------

function addMonoAt(target, source, at, gain, pan) {
  const angle = ((Math.max(-1, Math.min(1, pan)) + 1) * Math.PI) / 4;
  const leftGain = Math.SQRT2 * Math.cos(angle) * gain;
  const rightGain = Math.SQRT2 * Math.sin(angle) * gain;
  const length = target[0].length;
  for (let i = 0; i < source.length; i++) {
    const index = at + i;
    if (index >= length) break;
    if (index < 0) continue;
    target[0][index] += source[i] * leftGain;
    target[1][index] += source[i] * rightGain;
  }
}

function addStereoAt(target, source, at, gain) {
  const length = target[0].length;
  for (let i = 0; i < source[0].length; i++) {
    const index = at + i;
    if (index >= length) break;
    if (index < 0) continue;
    target[0][index] += source[0][i] * gain;
    target[1][index] += source[1][i] * gain;
  }
}

function peakOfChannels(channels) {
  let peak = 0;
  for (const channel of channels) {
    for (let i = 0; i < channel.length; i++) {
      const value = Math.abs(channel[i]);
      if (value > peak) peak = value;
    }
  }
  return peak;
}

function rmsOfChannels(channels, sampleRate, startSeconds, endSeconds) {
  const from = Math.max(0, Math.floor(startSeconds * sampleRate));
  const to = Math.min(channels[0].length, Math.ceil(endSeconds * sampleRate));
  if (to <= from) return 0;
  let sum = 0;
  let count = 0;
  for (const channel of channels) {
    for (let i = from; i < to; i++) {
      sum += channel[i] * channel[i];
      count++;
    }
  }
  return Math.sqrt(sum / Math.max(1, count));
}

function gateInterval(channels, sampleRate, startSeconds, endSeconds, fadeSeconds) {
  const start = Math.max(0, Math.floor(startSeconds * sampleRate));
  const end = Math.min(channels[0].length, Math.ceil(endSeconds * sampleRate));
  const fade = Math.max(1, Math.floor(fadeSeconds * sampleRate));
  for (const channel of channels) {
    const from = Math.max(0, start - fade);
    for (let i = from; i < start; i++) channel[i] *= (start - i) / fade;
    for (let i = start; i < end; i++) channel[i] = 0;
    for (let i = end; i < Math.min(channel.length, end + fade); i++) channel[i] *= (i - end) / fade;
  }
}

function applyTailFade(channels, sampleRate, score) {
  const fadeSeconds = 1.2;
  const end = channels[0].length;
  const start = Math.max(0, Math.min(end, Math.round((score.seconds - fadeSeconds) * sampleRate)));
  const span = Math.max(1, end - start);
  for (const channel of channels) {
    for (let i = start; i < end; i++) channel[i] *= (end - i) / span;
  }
}

function renderCoda(score, buses, sampleRate, seed) {
  const voices = [...new Set(score.coda.notes.map(note => note.voice))];
  const sourceLength = Math.ceil(score.coda.sourceSeconds * sampleRate);
  for (const voice of voices) {
    const source = [new Float32Array(sourceLength), new Float32Array(sourceLength)];
    for (const note of score.coda.notes) {
      if (note.voice !== voice) continue;
      const section = sectionById(note.section);
      const gain = STEM_GAINS[voice] * (section.dynamics[voice] ?? 1) * note.gain;
      const rendered = synthesize(voice, note.midi, {
        sampleRate,
        seed: seed + Math.round(note.sourceTime * 1000),
        velocity: note.velocity,
        hold: note.duration,
      });
      addMonoAt(source, rendered, Math.round(note.sourceTime * sampleRate), gain, note.pan);
    }
    // Same per-sample curve as buildScore's clock: the read position advances by
    // rate(outputTime) every output sample.
    const positions = new Float64Array(Math.ceil(sourceLength / CODA_RATE_END) + 8);
    let read = 0;
    let count = 0;
    while (read < sourceLength - 1 && count < positions.length) {
      positions[count] = read;
      read += codaRateAt(count / sampleRate);
      count++;
    }
    const left = new Float32Array(count);
    const right = new Float32Array(count);
    for (let i = 0; i < count; i++) {
      const position = positions[i];
      const index = Math.floor(position);
      const fraction = position - index;
      const next = Math.min(sourceLength - 1, index + 1);
      left[i] = source[0][index] * (1 - fraction) + source[0][next] * fraction;
      right[i] = source[1][index] * (1 - fraction) + source[1][next] * fraction;
    }
    addStereoAt(buses[voice], [left, right], Math.round(score.coda.start * sampleRate), 1);
  }
}

/**
 * Render exactly `frames` samples per channel by rebuilding the descriptor from
 * `params`; the caller never supplies a descriptor.
 *
 * The sample rate is the synthesis clock; `frames` is the authoritative span.
 * No wall clock, network or Math.random is used, so the same inputs produce the
 * same bytes in the same browser build. A span shorter than the last audible
 * event is a loud authoring error, never a silent truncation.
 */
export function renderScore({ sampleRate, channels, frames, params = {}, seed = DEFAULT_SEED } = {}) {
  if (!Number.isInteger(sampleRate) || sampleRate < 8000 || sampleRate > 192000)
    throw new Error(`storybook-score: invalid sampleRate ${sampleRate}`);
  if (channels !== 1 && channels !== 2)
    throw new Error(`storybook-score: channels must be 1 or 2, got ${channels}`);
  if (!Number.isInteger(frames) || frames <= 0) throw new Error(`storybook-score: invalid render length ${frames}`);
  if (!Number.isInteger(seed)) throw new Error('storybook-score: seed must be an integer');

  const score = buildScore(params);
  const requiredFrames = Math.ceil(score.audibleEnd * sampleRate);
  if (frames < requiredFrames)
    throw new Error(
      `storybook-score: the Source renders ${frames} samples but the score needs ${requiredFrames} ` +
        `(${score.audibleEnd.toFixed(3)} s) before its last phrase and ring finish. Source.durationSamples is the render length: ` +
        'extend it and the sound target outputSamples together; create.mjs authors only a new Project.',
    );

  const buses = Object.fromEntries(
    Object.keys(STEM_GAINS).map(voice => [voice, [new Float32Array(frames), new Float32Array(frames)]]),
  );
  const sectionCache = new Map(score.sections.map(section => [section.id, section]));
  let eventIndex = 0;
  for (const event of score.events) {
    if (event.coda) continue;
    const section = sectionCache.get(event.section);
    if (!section) throw new Error(`storybook-score: event ${event.id} names unknown section ${event.section}`);
    const gain = STEM_GAINS[event.voice] * (section.dynamics[event.voice] ?? 1) * event.gain;
    if (gain === 0) continue;
    const rendered = synthesize(event.voice, event.midi, {
      sampleRate,
      seed: seed + eventIndex++,
      velocity: event.velocity,
      hold: event.duration,
    });
    addMonoAt(buses[event.voice], rendered, Math.round(event.time * sampleRate), gain, event.pan);
  }
  renderCoda(score, buses, sampleRate, seed);

  // Dry sum, deterministic room send, then the authored rest and tail.
  let mix = [new Float32Array(frames), new Float32Array(frames)];
  for (const voice of Object.keys(buses)) addStereoAt(mix, buses[voice], 0, 1);
  const send = new Float32Array(frames);
  for (let i = 0; i < frames; i++) send[i] = (mix[0][i] + mix[1][i]) * 0.5;
  const wet = room(send, sampleRate);
  for (let i = 0; i < frames; i++) {
    mix[0][i] += wet[0][i] * 0.16;
    mix[1][i] += wet[1][i] * 0.16;
  }
  for (const rest of score.rests) gateInterval(mix, sampleRate, rest.start, rest.end, rest.fadeSeconds);
  applyTailFade(mix, sampleRate, score);
  const rawPeak = peakOfChannels(mix);
  let normalisationScale = 1;
  if (rawPeak > 0.92) {
    normalisationScale = 0.92 / rawPeak;
    for (const channel of mix) for (let i = 0; i < channel.length; i++) channel[i] *= normalisationScale;
  }
  const preGainPeak = peakOfChannels(mix);
  if (score.gain !== 1) for (const channel of mix) for (let i = 0; i < channel.length; i++) channel[i] *= score.gain;
  const delivered =
    channels === 1
      ? [
          (() => {
            const mono = new Float32Array(frames);
            for (let i = 0; i < frames; i++) mono[i] = (mix[0][i] + mix[1][i]) * 0.5;
            return mono;
          })(),
        ]
      : mix;
  const peak = peakOfChannels(delivered);
  if (peak > 1)
    throw new Error(`storybook-score: measured peak ${peak} exceeds full scale; this is an authoring bug, not a clamp`);

  const report = {
    variant: score.variant,
    transpose: score.transpose,
    key: score.key,
    baseKey: score.baseKey,
    meter: score.meter,
    meterSpec: score.meterSpec,
    meterLabel: score.meterLabel,
    gain: score.gain,
    seconds: score.seconds,
    sampleRate,
    channels,
    frames,
    events: score.events.length,
    rendered: score.events.length,
    rawPeak: roundTime(rawPeak),
    normalisationScale: roundTime(normalisationScale),
    preGainPeak: roundTime(preGainPeak),
    peak: roundTime(peak),
    rms: roundTime(rmsOfChannels(delivered, sampleRate, 0, score.seconds)),
    stemsScope:
      'dry voice buses before the room send, rest gate, tail fade, peak normalisation and gain; these are authoring meters, not delivered stems',
    sections: score.sections.map(section => ({
      id: section.id,
      role: section.role,
      start: section.start,
      end: section.end,
      rms: roundTime(rmsOfChannels(delivered, sampleRate, section.start, section.end)),
      dynamics: { ...section.dynamics },
    })),
    stems: Object.fromEntries(
      Object.entries(buses).map(([voice, bus]) => [
        voice,
        {
          gain: STEM_GAINS[voice],
          events: score.events.filter(event => event.voice === voice).length,
          rms: roundTime(rmsOfChannels(bus, sampleRate, 0, score.seconds)),
          peak: roundTime(peakOfChannels(bus)),
        },
      ]),
    ),
    rest: {
      start: score.rests[0].start,
      end: score.rests[0].end,
      rms: roundTime(rmsOfChannels(delivered, sampleRate, score.rests[0].start, score.rests[0].end)),
    },
    coda: {
      start: score.coda.start,
      end: score.coda.end,
      rateStart: score.coda.rateStart,
      rateEnd: score.coda.rateEnd,
      rampSeconds: score.coda.rampSeconds,
      curvePower: score.coda.curvePower,
      sourceSeconds: score.coda.sourceSeconds,
      lastOnset: score.coda.lastOnset,
      map: score.coda.map,
    },
    cues: score.cues.map(cue => ({ id: cue.id, time: cue.time })),
  };

  return { channels: delivered, report };
}
